#!/usr/bin/env bash
# Deploy Phase 1 of email-actions: the signed-link confirm-page service.
# Installs /root/vantaca-mcp/email-actions/{token,actions-server,email}.mjs, a
# systemd unit (vantaca-actions.service) listening on 127.0.0.1:8788, and an
# EMAIL_ACTION_SECRET in /root/vantaca-mcp/.env (generated once if absent).
#
# SAFE / not public yet: the service binds localhost only. It becomes reachable
# by email recipients ONLY after the Cloudflare tunnel is pointed at /a + /act
# (Phase 1b, wired once the tunnel config is known). Nothing sends email until
# Phase 2 (Gmail sender). Re-runnable.
set -euo pipefail
cd /root/vantaca-mcp
mkdir -p email-actions
printf %s "" | base64 -d > email-actions/token.mjs
printf %s "" | base64 -d > email-actions/actions-server.mjs
printf %s "" | base64 -d > email-actions/email.mjs
node --check email-actions/token.mjs
node --check email-actions/actions-server.mjs
node --check email-actions/email.mjs
echo SYNTAX_OK
if ! grep -q "^EMAIL_ACTION_SECRET=" .env 2>/dev/null; then
  echo "EMAIL_ACTION_SECRET=$(node -e "console.log(require('crypto').randomBytes(32).toString('hex'))")" >> .env
  echo "generated EMAIL_ACTION_SECRET in /root/vantaca-mcp/.env"
else
  echo "EMAIL_ACTION_SECRET already present"
fi
printf %s "" | base64 -d > /etc/systemd/system/vantaca-actions.service
systemctl daemon-reload
systemctl enable --now vantaca-actions.service
sleep 2
echo "actions:$(systemctl is-active vantaca-actions.service)"
curl -fsS -m 5 http://127.0.0.1:8788/health && echo " <- health ok" || echo " <- HEALTH FAILED (check: journalctl -u vantaca-actions -n 30)"

